begin;

create extension if not exists pgcrypto;
create extension if not exists citext;

do $$ begin
  create type public.member_role as enum ('owner','manager','reseller');
exception when duplicate_object then null; end $$;
do $$ begin
  create type public.invite_status as enum ('not_invited','pending','accepted','expired');
exception when duplicate_object then null; end $$;
do $$ begin
  create type public.product_status as enum ('available','unavailable');
exception when duplicate_object then null; end $$;
do $$ begin
  create type public.order_origin as enum ('direct','reseller');
exception when duplicate_object then null; end $$;
do $$ begin
  create type public.order_entry_type as enum ('detailed','general');
exception when duplicate_object then null; end $$;
do $$ begin
  create type public.order_status as enum ('pending','approved','paid','separating','shipped','delivered','cancelled');
exception when duplicate_object then null; end $$;
do $$ begin
  create type public.payment_method as enum ('pix','cash','card','transfer','other');
exception when duplicate_object then null; end $$;
do $$ begin
  create type public.payment_status as enum ('pending','paid','partially_paid','refunded');
exception when duplicate_object then null; end $$;
do $$ begin
  create type public.inventory_movement_type as enum ('initial_balance','sale','cancellation','manual_adjustment','return');
exception when duplicate_object then null; end $$;

create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null, email citext, phone text, auth_subject_legacy text, login_method text, last_signed_in_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.organizations (id uuid primary key default gen_random_uuid(), name text not null, slug citext not null unique, owner_profile_id uuid not null references public.profiles(id), timezone text not null default 'America/Sao_Paulo', currency char(3) not null default 'BRL' check (currency = 'BRL'), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.organization_members (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, profile_id uuid not null references public.profiles(id) on delete cascade, role public.member_role not null, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (organization_id, profile_id));
create table if not exists public.reseller_profiles (member_id uuid primary key references public.organization_members(id) on delete cascade, city text not null, commission_rate numeric(5,2) not null default 0 check (commission_rate between 0 and 100), invite_status public.invite_status not null default 'not_invited', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.reseller_invites (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, member_id uuid references public.organization_members(id) on delete set null, email citext, token_hash text not null unique, status public.invite_status not null default 'pending', expires_at timestamptz not null, accepted_at timestamptz, created_by uuid not null references public.profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.customers (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, full_name text not null, phone text, phone_normalized text, email citext, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create unique index if not exists customers_org_phone_unique on public.customers(organization_id, phone_normalized) where phone_normalized is not null and deleted_at is null;
create table if not exists public.products (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, name text not null, name_normalized text not null, category text not null, description text, sale_price numeric(12,2) not null check (sale_price >= 0), stock_on_hand integer not null default 1 check (stock_on_hand >= 0), status public.product_status not null default 'available', accent_color text, show_in_store boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, unique (organization_id, name_normalized));
create table if not exists public.product_private_costs (organization_id uuid not null references public.organizations(id) on delete cascade, product_id uuid not null references public.products(id) on delete cascade, cost_base numeric(12,2) not null check (cost_base >= 0), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), primary key (organization_id, product_id));
create table if not exists public.product_media (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, product_id uuid not null references public.products(id) on delete cascade, storage_bucket text not null default 'product-media', storage_path text not null, kind text not null default 'main', mime_type text, byte_size bigint check (byte_size is null or byte_size >= 0), sort_order integer not null default 0, created_at timestamptz not null default now(), unique (organization_id, storage_path));
create table if not exists public.product_variations (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, product_id uuid not null references public.products(id) on delete cascade, name text not null, created_at timestamptz not null default now());
create table if not exists public.product_variation_options (id uuid primary key default gen_random_uuid(), variation_id uuid not null references public.product_variations(id) on delete cascade, value text not null, unique (variation_id, value));
create table if not exists public.tags (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, name text not null, name_normalized text not null, unique (organization_id, name_normalized));
create table if not exists public.product_tags (product_id uuid not null references public.products(id) on delete cascade, tag_id uuid not null references public.tags(id) on delete cascade, primary key (product_id, tag_id));
create table if not exists public.collections (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, name text not null, description text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (organization_id, name));
create table if not exists public.collection_products (collection_id uuid not null references public.collections(id) on delete cascade, product_id uuid not null references public.products(id) on delete cascade, created_at timestamptz not null default now(), primary key (collection_id, product_id));
create table if not exists public.orders (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, created_by_profile_id uuid not null references public.profiles(id), reseller_member_id uuid references public.organization_members(id) on delete set null, customer_id uuid references public.customers(id) on delete set null, origin public.order_origin not null, entry_type public.order_entry_type not null, status public.order_status not null default 'pending', payment_method public.payment_method not null default 'other', payment_status public.payment_status not null default 'pending', sale_date timestamptz not null, manual_description text, total_amount numeric(12,2) not null check (total_amount >= 0), commission_amount numeric(12,2) not null default 0 check (commission_amount >= 0), commission_rate numeric(5,2) not null default 0 check (commission_rate between 0 and 100), customer_name_snapshot text, customer_phone_snapshot text, legacy_payload jsonb, request_id text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), cancelled_at timestamptz, unique (organization_id, request_id), check ((origin = 'reseller' and reseller_member_id is not null) or origin = 'direct'), check ((entry_type = 'general' and manual_description is not null) or entry_type = 'detailed'));
create table if not exists public.order_items (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, product_id uuid references public.products(id) on delete set null, item_type text not null check (item_type in ('product','general')), product_name_snapshot text not null, unit_price numeric(12,2) not null check (unit_price >= 0), quantity integer not null check (quantity > 0), subtotal numeric(12,2) not null check (subtotal >= 0), created_at timestamptz not null default now(), check ((item_type = 'product' and product_id is not null) or (item_type = 'general' and product_id is null)));
create table if not exists public.order_status_history (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, order_id uuid not null references public.orders(id) on delete cascade, from_status public.order_status, to_status public.order_status not null, changed_by_profile_id uuid not null references public.profiles(id), changed_at timestamptz not null default now(), metadata jsonb);
create table if not exists public.order_payments (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, order_id uuid not null references public.orders(id) on delete cascade, method public.payment_method not null, status public.payment_status not null, amount numeric(12,2) not null check (amount >= 0), paid_at timestamptz, external_reference text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.inventory_movements (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, product_id uuid not null references public.products(id) on delete cascade, order_id uuid references public.orders(id) on delete set null, movement_type public.inventory_movement_type not null, quantity_delta integer not null check (quantity_delta <> 0), reason text, created_by_profile_id uuid not null references public.profiles(id), created_at timestamptz not null default now());
create table if not exists public.notifications (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, recipient_profile_id uuid not null references public.profiles(id) on delete cascade, type text not null, entity_type text, entity_id uuid, title text not null, message text not null, read_at timestamptz, metadata jsonb, created_at timestamptz not null default now());
create table if not exists public.organization_settings (organization_id uuid primary key references public.organizations(id) on delete cascade, default_commission_rate numeric(5,2) not null default 0 check (default_commission_rate between 0 and 100), invite_expiry_days integer not null default 7 check (invite_expiry_days between 1 and 90), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.user_preferences (profile_id uuid not null references public.profiles(id) on delete cascade, organization_id uuid not null references public.organizations(id) on delete cascade, reseller_view text check (reseller_view in ('grid','list')), dashboard_period text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), primary key (profile_id, organization_id));
create table if not exists public.audit_events (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, actor_profile_id uuid references public.profiles(id) on delete set null, action text not null, entity_type text not null, entity_id uuid, before_data jsonb, after_data jsonb, request_id text, metadata jsonb, created_at timestamptz not null default now());
create table if not exists public.idempotency_keys (organization_id uuid not null references public.organizations(id) on delete cascade, request_id text not null, operation text not null, resource_id uuid, response jsonb, created_at timestamptz not null default now(), expires_at timestamptz, primary key (organization_id, request_id, operation));

create index if not exists members_org_idx on public.organization_members(organization_id, is_active);
create index if not exists products_org_idx on public.products(organization_id, status) where deleted_at is null;
create index if not exists orders_org_date_idx on public.orders(organization_id, sale_date desc);
create index if not exists orders_org_status_idx on public.orders(organization_id, status);
create index if not exists orders_reseller_date_idx on public.orders(organization_id, reseller_member_id, sale_date desc);
create index if not exists orders_customer_date_idx on public.orders(organization_id, customer_id, sale_date desc);
create index if not exists order_items_order_idx on public.order_items(order_id);
create index if not exists inventory_product_idx on public.inventory_movements(organization_id, product_id, created_at desc);
create index if not exists notifications_recipient_idx on public.notifications(recipient_profile_id, read_at, created_at desc);
create index if not exists audit_org_date_idx on public.audit_events(organization_id, created_at desc);

create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at = now(); return new; end $$;

create or replace function public.handle_new_auth_user() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles(id, full_name, email) values (new.id, coalesce(new.raw_user_meta_data->>'full_name', new.email, 'Usuário'), new.email) on conflict (id) do update set email = excluded.email, updated_at = now(); return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_auth_user();

create or replace function public.is_org_member(target_org uuid) returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from public.organization_members m where m.organization_id = target_org and m.profile_id = auth.uid() and m.is_active); $$;
create or replace function public.has_org_role(target_org uuid, allowed_roles public.member_role[]) returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from public.organization_members m where m.organization_id = target_org and m.profile_id = auth.uid() and m.is_active and m.role = any(allowed_roles)); $$;

create or replace view public.v_product_inventory as select p.organization_id, p.id as product_id, p.name, p.stock_on_hand + coalesce(sum(im.quantity_delta), 0) as available_units from public.products p left join public.inventory_movements im on im.product_id = p.id and im.movement_type <> 'initial_balance' where p.deleted_at is null group by p.organization_id, p.id, p.name, p.stock_on_hand;
create or replace view public.v_customer_ltv as select c.organization_id, c.id as customer_id, c.full_name, count(o.id)::integer as order_count, coalesce(sum(o.total_amount),0)::numeric(12,2) as total_purchased, max(o.sale_date) as last_order_at from public.customers c left join public.orders o on o.customer_id = c.id and o.status <> 'cancelled' where c.deleted_at is null group by c.organization_id, c.id, c.full_name;

do $$ declare t text; begin foreach t in array array['profiles','organizations','organization_members','reseller_profiles','reseller_invites','customers','products','product_private_costs','product_media','product_variations','product_variation_options','tags','product_tags','collections','collection_products','orders','order_items','order_status_history','order_payments','inventory_movements','notifications','organization_settings','user_preferences','audit_events','idempotency_keys'] loop execute format('alter table public.%I enable row level security', t); execute format('revoke all on table public.%I from anon', t); execute format('revoke all on table public.%I from authenticated', t); end loop; end $$;
grant select, insert, update, delete on all tables in schema public to authenticated;

drop policy if exists profiles_self on public.profiles; create policy profiles_self on public.profiles for all to authenticated using (id = auth.uid()) with check (id = auth.uid());
drop policy if exists org_member_access on public.organization_members; create policy org_member_access on public.organization_members for select to authenticated using (is_org_member(organization_id));
drop policy if exists org_manager_members on public.organization_members; create policy org_manager_members on public.organization_members for all to authenticated using (has_org_role(organization_id, array['owner','manager']::public.member_role[])) with check (has_org_role(organization_id, array['owner','manager']::public.member_role[]));
drop policy if exists org_access on public.organizations; create policy org_access on public.organizations for select to authenticated using (is_org_member(id));
drop policy if exists org_manager_org on public.organizations; create policy org_manager_org on public.organizations for update to authenticated using (has_org_role(id, array['owner','manager']::public.member_role[])) with check (has_org_role(id, array['owner','manager']::public.member_role[]));

do $$ declare t text; begin foreach t in array array['reseller_invites','customers','products','product_media','product_variations','tags','collections','orders','order_status_history','order_payments','inventory_movements','notifications','organization_settings','user_preferences','audit_events','idempotency_keys'] loop execute format('drop policy if exists tenant_select on public.%I', t); execute format('create policy tenant_select on public.%I for select to authenticated using (is_org_member(organization_id))', t); execute format('drop policy if exists tenant_manager_write on public.%I', t); execute format('create policy tenant_manager_write on public.%I for all to authenticated using (has_org_role(organization_id, array[''owner'',''manager'']::public.member_role[])) with check (has_org_role(organization_id, array[''owner'',''manager'']::public.member_role[]))', t); end loop; end $$;

drop policy if exists private_cost_manager on public.product_private_costs; create policy private_cost_manager on public.product_private_costs for all to authenticated using (has_org_role(organization_id, array['owner','manager']::public.member_role[])) with check (has_org_role(organization_id, array['owner','manager']::public.member_role[]));

drop policy if exists reseller_profile_select on public.reseller_profiles; create policy reseller_profile_select on public.reseller_profiles for select to authenticated using (exists (select 1 from public.organization_members m where m.id = member_id and is_org_member(m.organization_id)));
drop policy if exists reseller_profile_manager on public.reseller_profiles; create policy reseller_profile_manager on public.reseller_profiles for all to authenticated using (exists (select 1 from public.organization_members m where m.id = member_id and has_org_role(m.organization_id, array['owner','manager']::public.member_role[]))) with check (exists (select 1 from public.organization_members m where m.id = member_id and has_org_role(m.organization_id, array['owner','manager']::public.member_role[])));
drop policy if exists order_items_select on public.order_items; create policy order_items_select on public.order_items for select to authenticated using (exists (select 1 from public.orders o where o.id = order_id and is_org_member(o.organization_id)));
drop policy if exists order_items_manager on public.order_items; create policy order_items_manager on public.order_items for all to authenticated using (exists (select 1 from public.orders o where o.id = order_id and has_org_role(o.organization_id, array['owner','manager']::public.member_role[]))) with check (exists (select 1 from public.orders o where o.id = order_id and has_org_role(o.organization_id, array['owner','manager']::public.member_role[])));
drop policy if exists variation_options_select on public.product_variation_options; create policy variation_options_select on public.product_variation_options for select to authenticated using (exists (select 1 from public.product_variations v where v.id = variation_id and is_org_member(v.organization_id)));
drop policy if exists variation_options_manager on public.product_variation_options; create policy variation_options_manager on public.product_variation_options for all to authenticated using (exists (select 1 from public.product_variations v where v.id = variation_id and has_org_role(v.organization_id, array['owner','manager']::public.member_role[]))) with check (exists (select 1 from public.product_variations v where v.id = variation_id and has_org_role(v.organization_id, array['owner','manager']::public.member_role[])));
drop policy if exists product_tags_select on public.product_tags; create policy product_tags_select on public.product_tags for select to authenticated using (exists (select 1 from public.products p where p.id = product_id and is_org_member(p.organization_id)));
drop policy if exists product_tags_manager on public.product_tags; create policy product_tags_manager on public.product_tags for all to authenticated using (exists (select 1 from public.products p where p.id = product_id and has_org_role(p.organization_id, array['owner','manager']::public.member_role[]))) with check (exists (select 1 from public.products p where p.id = product_id and has_org_role(p.organization_id, array['owner','manager']::public.member_role[])));
drop policy if exists collection_products_select on public.collection_products; create policy collection_products_select on public.collection_products for select to authenticated using (exists (select 1 from public.collections c where c.id = collection_id and is_org_member(c.organization_id)));
drop policy if exists collection_products_manager on public.collection_products; create policy collection_products_manager on public.collection_products for all to authenticated using (exists (select 1 from public.collections c where c.id = collection_id and has_org_role(c.organization_id, array['owner','manager']::public.member_role[]))) with check (exists (select 1 from public.collections c where c.id = collection_id and has_org_role(c.organization_id, array['owner','manager']::public.member_role[])));

commit;
